create schema store;
create function store.touch() returns trigger language plpgsql as $$ begin new.updated_at=clock_timestamp(); return new; end $$;
create table store.sites (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, region text not null, owner text not null, country text not null check(country in ('NZ','AU','OTHER')), cadence_days integer not null default 30 check(cadence_days>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table store.standards (id uuid primary key default gen_random_uuid(), code text not null unique, section text not null, question text not null, weight integer not null check(weight between 1 and 100), critical boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table store.audits (id uuid primary key default gen_random_uuid(), code text not null unique, site_id uuid not null references store.sites, title text not null, auditor text not null, due_date date not null, visited_on date, status text not null default 'planned' check(status in ('planned','submitted','imported')), source_key text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table store.checks (id uuid primary key default gen_random_uuid(), audit_id uuid not null references store.audits, standard_id uuid references store.standards, code text not null, section text not null, question text not null, weight integer not null check(weight between 1 and 100), critical boolean not null default false, outcome text check(outcome in ('pass','fail','na')), note text not null default '', source_key text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(audit_id,code));
create table store.evidence (id uuid primary key default gen_random_uuid(), code text not null unique, check_id uuid not null references store.checks, reference text not null, personal boolean not null default false, purpose text not null, access_owner text not null, review_on date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table store.actions (id uuid primary key default gen_random_uuid(), code text not null unique, check_id uuid not null references store.checks, title text not null, owner text not null, due_date date not null, state text not null default 'open' check(state in ('open','completed','verified')), resolution text, evidence_id uuid references store.evidence, completed_by text, verified_by text, revisit_on date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(state='open' or (resolution is not null and evidence_id is not null and completed_by is not null)), check(state<>'verified' or (verified_by is not null and lower(verified_by)<>lower(completed_by))));
create table store.import_batches (id uuid primary key default gen_random_uuid(), source text not null, file_hash text not null, row_count integer not null, actor text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table store.source_rows (id uuid primary key default gen_random_uuid(), source_key text not null unique, batch_id uuid not null references store.import_batches, check_id uuid not null references store.checks, raw jsonb not null, fingerprint text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table store.activity (id uuid primary key default gen_random_uuid(), entity text not null, record_id uuid, operation text not null, actor text not null, reason text not null, before_data jsonb, after_data jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create function store.immutable() returns trigger language plpgsql as $$ begin raise exception 'Source and history records are immutable'; end $$;
create trigger history_immutable before update or delete on store.activity for each row execute function store.immutable();
create trigger source_immutable before update or delete on store.source_rows for each row execute function store.immutable();
create function store.record_change() returns trigger language plpgsql as $$ begin
 insert into store.activity(entity,record_id,operation,actor,reason,before_data,after_data) values(TG_TABLE_NAME,coalesce(new.id,old.id),TG_OP,coalesce(nullif(current_setting('store.actor',true),''),'unlabelled'),coalesce(current_setting('store.reason',true),''),case when TG_OP<>'INSERT' then to_jsonb(old) end,case when TG_OP<>'DELETE' then to_jsonb(new) end); return coalesce(new,old); end $$;
create function store.protect_check() returns trigger language plpgsql as $$ declare s text; begin
 select status into s from store.audits where id=coalesce(new.audit_id,old.audit_id);
 if TG_OP<>'INSERT' and s<>'planned' then raise exception 'Submitted and imported checks are immutable'; end if;
 if TG_OP='UPDATE' and (new.audit_id<>old.audit_id or new.question<>old.question or new.code<>old.code or new.weight<>old.weight or new.critical<>old.critical) then raise exception 'Checklist snapshot is immutable'; end if;
 return coalesce(new,old); end $$;
create trigger checks_guard before update or delete on store.checks for each row execute function store.protect_check();
DO $$ declare t text; begin foreach t in array array['sites','standards','audits','checks','evidence','actions','import_batches'] loop
 execute format('create trigger touch before update on store.%I for each row execute function store.touch()',t);
 execute format('create trigger change after insert or update or delete on store.%I for each row execute function store.record_change()',t);
 end loop;
 foreach t in array array['sites','standards','audits','checks','evidence','actions','import_batches','source_rows','activity'] loop
 execute format('alter table store.%I enable row level security',t); execute format('revoke all on store.%I from public',t);
 end loop; end $$;
revoke all on schema store from public;
create view store.scorecard as
select a.id,a.code,a.title,s.name site,s.region,a.status,a.due_date,a.visited_on,
 count(c.id)::integer total_checks,count(c.id) filter(where c.outcome is null)::integer unanswered,
 count(c.id) filter(where c.outcome='fail')::integer failures,
 count(c.id) filter(where c.outcome='fail' and c.critical)::integer critical_failures,
 case when a.status='imported' then null else round(100.0*sum(case when c.outcome='pass' then c.weight else 0 end)/nullif(sum(case when c.outcome in ('pass','fail') then c.weight else 0 end),0),1) end score_pct,
 case when a.status='imported' then 'Imported history: review mapping' when count(c.id) filter(where c.outcome is null)>0 then 'Incomplete' when count(c.id) filter(where c.outcome='fail' and c.critical)>0 then 'Critical failure' else 'Scored' end verdict
from store.audits a join store.sites s on s.id=a.site_id left join store.checks c on c.audit_id=a.id group by a.id,s.name,s.region;
create view store.action_register as select x.id,x.code,s.name site,a.code audit,c.code check_code,x.title,x.owner,x.due_date,x.state,x.revisit_on,x.resolution,e.reference evidence,x.completed_by,x.verified_by from store.actions x join store.checks c on c.id=x.check_id join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id left join store.evidence e on e.id=x.evidence_id;
create view store.repeat_failures as select s.name site,c.code check_code,c.question,count(distinct a.id)::integer failed_visits,max(a.visited_on) latest_visit from store.checks c join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where c.outcome='fail' and a.status in ('submitted','imported') group by s.id,s.name,c.code,c.question having count(distinct a.id)>1;
create view store.coverage as select s.id,s.code,s.name,s.owner,s.region,s.cadence_days,max(a.visited_on) last_visit,max(a.visited_on)+s.cadence_days next_visit,case when max(a.visited_on) is null then 'Never visited' when max(a.visited_on)+s.cadence_days<current_date then 'Overdue' else 'Current' end coverage from store.sites s left join store.audits a on a.site_id=s.id and a.status in ('submitted','imported') group by s.id;
create view store.compliance_findings as
select 'EVIDENCE_REVIEW' rule,e.code reference,s.name site,'Review purpose, access and retention for this evidence' finding from store.evidence e join store.checks c on c.id=e.check_id join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where e.review_on<current_date
union all select 'FAILURE_WITHOUT_ACTION',a.code||'/'||c.code,s.name,'Failed check has no corrective action' from store.checks c join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where c.outcome='fail' and not exists(select 1 from store.actions x where x.check_id=c.id)
union all select 'UNANSWERED_IMPORT',a.code||'/'||c.code,s.name,'Source answer needs mapping review' from store.checks c join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where a.status='imported' and c.outcome is null
union all select 'OVERDUE_ACTION',x.code,s.name,'Corrective action is past due and not verified' from store.actions x join store.checks c on c.id=x.check_id join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where x.state<>'verified' and x.due_date<current_date;
